		</template>
	</section></div></Transition></Teleport>
	<Teleport to="body"><Transition name="account-window"><div v-if="shareOpen" class="account-overlay share-overlay" @click.self="shareOpen=false"><section class="share-dialog" role="dialog" aria-modal="true" aria-label="分享故事"><header><div><strong>分享故事</strong><small>任何拿到链接的人都可以直接在播放器中观看当前云端版本。</small></div><button class="icon-button" aria-label="关闭分享" @click="shareOpen=false"><svg viewBox="0 0 20 20"><path d="m5 5 10 10M15 5 5 15"/></svg></button></header><div><input :value="shareUrl" readonly aria-label="故事分享链接" @focus="selectShareInput"/><button class="primary" @click="copyShareUrl">{{ shareCopied?'已复制':'复制链接' }}</button></div></section></div></Transition></Teleport>
	<Teleport to="body"><Transition name="account-window"><div v-if="captcha.show" class="captcha-overlay" @click.self="captcha.show=false"><section role="dialog" aria-modal="true"><h3>人机验证</h3><p>发送邮件或异常行为需要先验证。</p><div v-if="captcha.provider==='image'"><div class="captcha-image" v-html="captcha.image"></div><input v-model="captcha.answer" placeholder="输入图中的字符" autocomplete="off"/></div><altcha-widget v-else-if="captcha.provider==='altcha'" ref="altchaEl" language="zh-cn" workers="1" @statechange="onAltchaState"/><div v-else ref="externalCaptcha"></div><p class="mail-hint">验证邮件可能被归类为垃圾邮件或广告邮件，请同时检查这些文件夹。</p><p v-if="captcha.error" class="notice">{{ captcha.error }}</p><footer><button @click="captcha.show=false">取消</button><button v-if="captcha.provider==='image'" class="primary" @click="verifyCaptcha">验证</button></footer></section></div></Transition></Teleport>
</template>

<script setup lang="ts">
import "altcha";
import { computed, defineComponent, h, nextTick, onMounted, reactive, ref } from "vue";
